-- Steel catalogue import — Vulcan price list dated 2026-05-18 (857 items, 18 types).
-- Per-metre cost basis (MTR Price); plate tabs use per-sheet (EAC). kg/unit = MTR weight (per-sheet for plate).
-- Source: docs/RODIER STEEL PRICE LIST 18TH MAY 26.xlsx (kept local, gitignored).
BEGIN;

ALTER TABLE materials ADD COLUMN IF NOT EXISTS mtr_weight NUMERIC(12,4); -- kg per unit (per metre; per sheet for plate) -> feeds galvanising weight

-- Steel section taxonomy (subsection = steel type / spreadsheet tab)
DELETE FROM costing_sections WHERE section = 'Steel';

-- Re-import is safe: clear existing Steel materials then reload
DELETE FROM materials WHERE section = 'Steel';

COMMIT;
